+// runLoop entry guard (hank): suppress invalid consecutive assistant messages (clone wars; attack of the clones)
+function ensureStrictTurnTaking(rawMsgs: SessionV1.WithParts[]): SessionV1.WithParts[] {
+  if (!rawMsgs || rawMsgs.length < 2) return rawMsgs
+
+  const processed = rawMsgs.reduce((clonedArray, currentMsg) => {
+    // clone the message and its nested parts to stop any bleeding (triage)
+    const clonedMsg: SessionV1.WithParts = {
+      ...currentMsg,
+      info: { ...currentMsg.info },
+      parts: currentMsg.parts
+        ? currentMsg.parts.map((p: SessionV1.Part) => ({
+            ...p,
+            ...(p.type === "tool" ? { state: { ...p.state } } : {}),
+          }))
+        : [],
+    }
+
+    if (clonedArray.length === 0) {
+      clonedArray.push(clonedMsg)
+      return clonedArray
+    }
+
+    const previousMsg = clonedArray[clonedArray.length - 1]
+
+    // catch consecutive assistant messages (invalid)
+    if (previousMsg.info.role === "assistant" && clonedMsg.info.role === "assistant") {
+      // merge the parts together (text, tool calls, reasoning blocks)
+      const mergedParts = [...(previousMsg.parts || []), ...(clonedMsg.parts || [])]
+
+      // mutate the clone, not the original state
+      clonedArray[clonedArray.length - 1] = {
+        ...previousMsg,
+        parts: mergedParts,
+        // fwiw; if the schema schema uses an updated timestamp or ID for the combined payload then assign it here, but keep in mind that the sdks usually ignore ids.
+      }
+    } else {
+      // clean turn; push the cloned message
+      clonedArray.push(clonedMsg)
+    }
+
+    return clonedArray
+  }, [] as SessionV1.WithParts[])
+
+  return processed
+}
